from collections import Counter

def sort_chars_by_frequency(s):
    counts = Counter(s)
    order = sorted(counts.keys(), key=lambda c: (-counts[c], c))
    return ''.join(c * counts[c] for c in order)

from decimal import Decimal, ROUND_HALF_UP

def percentile_rank_of_value(scores, value):
    if not scores:
        return 0
    count = sum(1 for s in scores if s <= value)
    pct = 100 * count / len(scores)
    return int(Decimal(str(pct)).quantize(Decimal(1), rounding=ROUND_HALF_UP))

