def percentile_rank_strict(scores, value):
    if not scores:
        return 0.0
    count = sum(1 for s in scores if s < value)
    pct = 100 * count / len(scores)
    return float(Decimal(str(pct)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

