def rank_normalize_scores(scores):
    n = len(scores)
    if n <= 1:
        return [0.0] * n
    sorted_scores = sorted(scores)
    first_index = {}
    for i, v in enumerate(sorted_scores):
        if v not in first_index:
            first_index[v] = i
    def r4(x):
        return float(Decimal(str(x)).quantize(Decimal('0.0001'), rounding=ROUND_HALF_UP))
    return [r4(first_index[v] / (n - 1)) for v in scores]

