def rank_normalize_scores_avg_tie(scores):
    n = len(scores)
    if n <= 1:
        return [0.0] * n
    sorted_scores = sorted(scores)
    positions = {}
    i = 0
    while i < n:
        j = i
        while j < n and sorted_scores[j] == sorted_scores[i]:
            j += 1
        avg_pos = sum(range(i, j)) / (j - i)
        positions[sorted_scores[i]] = avg_pos
        i = j
    def r4(x):
        return float(Decimal(str(x)).quantize(Decimal('0.0001'), rounding=ROUND_HALF_UP))
    return [r4(positions[v] / (n - 1)) for v in scores]

