def normalize_ranks_dense(scores):
    n = len(scores)
    distinct_sorted = sorted(set(scores))
    m = len(distinct_sorted)
    if m <= 1:
        return [0.0] * n
    rank = {v: i for i, v in enumerate(distinct_sorted)}
    def r4(x):
        return float(Decimal(str(x)).quantize(Decimal('0.0001'), rounding=ROUND_HALF_UP))
    return [r4(rank[v] / (m - 1)) for v in scores]

def closest_k_to_target(nums, target, k):
    ordered = sorted(nums, key=lambda x: (abs(x - target), x))
    return ordered[:k]

def farthest_k_from_target(nums, target, k):
    ordered = sorted(nums, key=lambda x: (-abs(x - target), -x))
    return ordered[:k]

def closest_k_indices_to_target(nums, target, k):
    order = sorted(range(len(nums)), key=lambda i: (abs(nums[i] - target), i))
    return order[:k]

def rank_by_distance_from_median(nums):
    n = len(nums)
    sorted_nums = sorted(nums)
    if n % 2 == 1:
        median = sorted_nums[n // 2]
    else:
        median = (sorted_nums[n // 2 - 1] + sorted_nums[n // 2]) / 2
    return sorted(nums, key=lambda x: (abs(x - median), x))

