def top_unique_score_names(records, k):
    first_name_for_score = {}
    for name, score in records:
        if score not in first_name_for_score:
            first_name_for_score[score] = name
    distinct_scores = sorted(first_name_for_score.keys(), reverse=True)
    return [first_name_for_score[s] for s in distinct_scores[:k]]
